//! Kinora — a fast, private photo and video viewer.
//!
//! Application entry point (the Rust equivalent of `Program.cs`): sets up logging,
//! creates the main window and runs the UI event loop.

// In release builds on Windows, don't open a console window next to the app.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use anyhow::Context as _;
use slint::ComponentHandle as _;
use tracing_subscriber::EnvFilter;

/// Rust code generated by Slint from `ui/*.slint` (see `build.rs`).
mod ui {
    // The generated code is not ours and trips exactly these workspace lints (checked with
    // clippy 1.99 / Slint 1.18.1). The allowance is scoped to this module only — our own
    // code keeps the full lint set. Re-check this list when upgrading Slint.
    #![allow(
        clippy::unwrap_used,
        clippy::as_conversions,
        clippy::panic,
        clippy::indexing_slicing,
        missing_debug_implementations
    )]
    slint::include_modules!();
}

fn main() -> anyhow::Result<()> {
    init_logging()?;
    tracing::info!(version = env!("CARGO_PKG_VERSION"), "starting Kinora");

    let window = ui::AppWindow::new().context("could not create the main window")?;
    window.run().context("the UI event loop failed")?;

    tracing::info!("Kinora exited normally");
    Ok(())
}

/// Logs to stderr. The level comes from `RUST_LOG` (e.g. `RUST_LOG=debug`), default `info`.
/// A rotating log file in the OS log directory is added in Phase 2.
fn init_logging() -> anyhow::Result<()> {
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .try_init()
        .map_err(|err| anyhow::anyhow!(err))
        .context("could not initialise logging")
}
